<template>
  <div class="audio-import">
    <label class="audio-drop" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop">
      <strong>{{$t(busy?'Convirtiendo audio…':'Subir o arrastrar un audio')}}</strong>
      <span>{{ $t("WAV, MP3, M4A, OGG o FLAC · conversión automática") }}</span>
      <input type="file" accept="audio/*,.wav,.flac,.m4a,.ogg" :disabled="disabled||busy" @change="upload" />
    </label>
    <div v-if="source" class="trim-editor">
      <header><strong>{{source.name}}</strong><span>{{duration.toFixed(3)}} {{ $t("s ·") }} {{$t(source.conversion)}}</span></header>
      <p>{{ $t("Arrastra el clip para moverlo, sus bordes para recortar y los controles amarillos para crear fades. ↔ cambia la duración conservando el tono.") }}</p>
      <div class="timeline-ruler"><span v-for="i in 7" :key="i">{{(viewStart+(i-1)*viewSpan/6).toFixed(2)}} s</span></div>
      <div class="trim-track" ref="track">
        <div class="target-region" :style="{left:outputPercent(0)+'%',width:percentLength(maxDuration)+'%'}"></div>
        <div class="marker marker-start" :style="{left:outputPercent(0)+'%'}"><span>▼ {{ $t("Inicio") }} · 0 s</span></div>
        <div class="marker marker-end" :style="{left:outputPercent(maxDuration)+'%'}"><span>▼ {{ $t("Fin") }} · {{maxDuration.toFixed(3)}} s</span></div>
        <div class="clip-fill" :class="{overflow:clipEnd>maxDuration}" :style="{left:percent(start)+'%',width:percentLength(outputDuration)+'%'}"></div>
        <canvas ref="wave" width="1200" height="220" role="img" :aria-label="$t('Forma de onda del audio subido')" />
        <div class="trim-selection" :style="{left:percent(start)+'%',width:percentLength(outputDuration)+'%'}" @pointerdown="begin($event,'move')" @pointermove="move" @pointerup="finish" @pointercancel="finish" role="button" tabindex="0" :aria-label="$t('Mover clip')" @keydown.left.prevent="shift(-.01)" @keydown.right.prevent="shift(.01)"><span class="clip-title">{{source.name}} · {{Math.round(stretch*100)}} %</span></div>
        <svg class="fade-envelope" viewBox="0 0 1000 160" preserveAspectRatio="none" :style="{left:percent(start)+'%',width:percentLength(outputDuration)+'%'}" aria-hidden="true"><path :d="fadePath" /></svg>
        <button v-for="kind in ['start','end']" :key="kind" class="trim-handle" :class="kind" :style="{left:'clamp(6px,'+percent(kind==='start'?start:end)+'%,calc(100% - 6px))'}" @pointerdown="begin($event,kind)" @pointermove="move" @pointerup="finish" @pointercancel="finish" @keydown.left.prevent="step(kind,-.01)" @keydown.right.prevent="step(kind,.01)" role="slider" :aria-label="$t(kind==='start'?'Inicio del recorte':'Fin del recorte')" :aria-valuemin="kind==='start'?0:start" :aria-valuemax="kind==='start'?end:duration" :aria-valuenow="kind==='start'?start:end">⋮</button>
        <button v-for="kind in ['in','out']" :key="kind" class="fade-handle" :style="{left:'clamp(11px,'+outputPercent(kind==='in'?offset+fadeIn:clipEnd-fadeOut)+'%,calc(100% - 11px))'}" @pointerdown="beginFade($event,kind)" @pointermove="moveFade" @pointerup="finishFade" @pointercancel="finishFade" @keydown.left.prevent="stepFade(kind,-.01)" @keydown.right.prevent="stepFade(kind,.01)" role="slider" :aria-label="kind==='in'?'Fade in':'Fade out'" :aria-valuemin="0" :aria-valuemax="outputDuration" :aria-valuenow="kind==='in'?fadeIn:fadeOut" :title="(kind==='in'?'Fade in':'Fade out')+' · '+(kind==='in'?fadeIn:fadeOut).toFixed(3)+' s'">◩</button>
        <button class="stretch-handle" :style="{left:percent(end)+'%'}" @pointerdown="beginStretch" @pointermove="moveStretch" @pointerup="finishStretch" @pointercancel="finishStretch" @keydown.left.prevent="setStretch(stretch-.01)" @keydown.right.prevent="setStretch(stretch+.01)" role="slider" :aria-label="$t('Stretch · duración (%)')" :aria-valuemin="10" :aria-valuemax="200" :aria-valuenow="Math.round(stretch*100)" title="Stretch">↔</button>
      </div>
      <p class="duration-summary"><strong>{{(end-start).toFixed(3)}} s</strong> {{ $t("de audio original") }} <span aria-hidden="true">→</span> <strong>{{outputDuration.toFixed(3)}} s</strong> {{ $t("en la ROM") }}</p>
      <div class="time-axis"><span>{{viewStart.toFixed(3)}} {{ $t("s") }}</span><span>{{(viewStart+viewSpan).toFixed(3)}} {{ $t("s") }}</span></div>
      <div class="view-controls"><button @click="zoom">{{ $t("Acercar al recorte") }}</button><button @click="overview">{{ $t("Ver audio completo") }}</button><label v-if="viewSpan<timelineDuration">{{ $t("Mover vista") }} <input type="range" min="0" :max="timelineDuration-viewSpan" :step="minimum" v-model.number="viewStart" @input="draw" :aria-label="$t(&quot;Desplazar vista del audio&quot;)" /></label></div>
      <div class="trim-controls">
        <label>{{ $t("Inicio (s)") }} <input type="number" min="0" :max="end-minimum" step="0.001" :value="start.toFixed(3)" @change="setStart(Number($event.target.value));commit()" /></label>
        <label>{{ $t("Fin (s)") }} <input type="number" :min="start+minimum" :max="duration" step="0.001" :value="end.toFixed(3)" @change="setEnd(Number($event.target.value));commit()" /></label>
        <label>{{ $t("Posición (s)") }} <input type="number" min="0" :max="Math.max(0,maxDuration-outputDuration)" step="0.001" :value="offset.toFixed(3)" @change="setOffset(Number($event.target.value));commit()" /></label>
        <label>Fade in (s) <input type="number" min="0" :max="outputDuration" step="0.001" :value="fadeIn.toFixed(3)" @change="setFade('in',Number($event.target.value));commit()" /></label>
        <label>Fade out (s) <input type="number" min="0" :max="outputDuration" step="0.001" :value="fadeOut.toFixed(3)" @change="setFade('out',Number($event.target.value));commit()" /></label>
        <label>{{ $t("Stretch · duración (%)") }} <input type="number" min="10" max="200" step="1" :value="Math.round(stretch*100)" @change="setStretch(Number($event.target.value)/100)" /></label>
        <button @click="fit">{{ $t("Ajustar a capacidad") }}</button><button @click="full">{{ $t("Audio completo") }}</button>
      </div>
      <p>{{ $t("Comprimir permite incluir más audio original en el mismo espacio. El tono se conserva.") }}</p>
      <div class="stretch-actions"><button @click="setStretch(1)">{{ $t("Restablecer 100 %") }}</button><button @click="fitStretch">{{ $t("Stretch para encajar en ROM") }}</button><span class="stretch-value">{{Math.round(stretch*100)}} % · {{outputDuration.toFixed(3)}} s</span></div>
      <p v-if="clipEnd>maxDuration" class="stretch-warning" role="status">{{ $t("El resultado supera el espacio disponible. Contrae el audio o ajusta el recorte antes de aplicar.") }}</p>
      <div class="trim-capacity"><span :style="{width:Math.min(100,clipEnd/maxDuration*100)+'%'}"></span></div>
      <p class="trim-status">{{ $t("Selección:") }} <strong>{{outputDuration.toFixed(3)}} {{ $t("s") }}</strong> / {{maxDuration.toFixed(3)}} {{ $t("s disponibles ·") }} {{$t(Math.round(clipEnd/maxDuration*100))}}{{ $t("% de capacidad") }}</p>
      <p v-if="duration>selectionCapacity&&outputDuration<=maxDuration" class="trim-hint">{{ $t("Se seleccionó un fragmento que cabe en la ROM. Puedes moverlo para conservar la parte que prefieras.") }}</p>
      <button :disabled="clipEnd>maxDuration||!!stretchDrag||!!drag||!!fadeDrag" @click="$emit('preview')">{{ $t("Escuchar recorte convertido") }}</button><button @click="$emit('discard')">{{ $t("Descartar audio subido") }}</button>
    </div>
  </div>
</template>
<script>
export default {
  props:{source:Object,maxDuration:Number,busy:Boolean,disabled:Boolean},emits:['upload','range','preview','discard','editing'],
  data(){return {start:0,end:0,stretch:1,offset:0,fadeIn:0,fadeOut:0,fadeInCurve:1,fadeOutCurve:1,fadeDrag:null,stretchDrag:null,drag:null,dragging:false,viewStart:0,viewSpan:1};},
  computed:{clipEnd(){return this.offset+this.outputDuration;},fadePath(){const length=this.outputDuration||1,a=this.fadeIn/length*1000,b=this.fadeOut/length*1000;let path='M 0 '+(a?158:8);for(let i=1;i<=32;i++){const x=a*i/32;path+=' L '+x+' '+(158-150*(i/32)**this.fadeInCurve);}path+=' L '+(1000-b)+' 8';for(let i=1;i<=32;i++)path+=' L '+(1000-b+b*i/32)+' '+(158-150*(1-i/32)**this.fadeOutCurve);return path;},timelineDuration(){return Math.max(this.maxDuration,this.clipEnd)*1.08;},outputDuration(){return (this.end-this.start)*this.stretch;},selectionCapacity(){return Math.max(this.minimum*this.stretch,this.maxDuration-this.offset)/this.stretch;},duration(){return this.source?this.source.samples.length/this.source.sampleRate:0;},minimum(){return this.source?1/this.source.sampleRate:.001;}},
  watch:{offset(){this.$nextTick(()=>this.draw());},start(){this.$nextTick(()=>this.draw());},end(){this.$nextTick(()=>this.draw());},stretch(){this.$nextTick(()=>this.draw());},source(){this.initialize();},maxDuration(){if(this.source){this.setOffset(this.offset);if(this.clipEnd>this.maxDuration)this.fit();else this.commit();}}},mounted(){if(this.source)this.initialize();},
  methods:{
    upload(event){const file=event.target.files?.[0];event.target.value='';if(file)this.$emit('upload',file);},
    drop(event){this.dragging=false;if(this.disabled||this.busy)return;const file=event.dataTransfer.files?.[0];if(file)this.$emit('upload',file);},
    outputPercent(time){return (time-this.viewStart)/this.viewSpan*100;},percent(time){return this.outputPercent(this.offset+(time-this.start)*this.stretch);},percentLength(time){return time/this.viewSpan*100;},
    initialize(){if(!this.source)return;this.offset=0;this.fadeIn=0;this.fadeOut=0;this.fadeInCurve=1;this.fadeOutCurve=1;this.stretch=1;this.start=0;this.end=Math.min(this.duration,Math.floor(this.selectionCapacity*this.source.sampleRate)/this.source.sampleRate);this.viewStart=0;this.viewSpan=this.timelineDuration;if(this.end/this.duration<.15)this.zoom();else this.$nextTick(()=>this.draw());this.commit();},
    waveSourceTime(time){return time<this.offset||time>=this.clipEnd?null:this.start+(time-this.offset)/this.stretch;},
    draw(){const canvas=this.$refs.wave;if(!canvas||!this.source)return;const ctx=canvas.getContext('2d'),samples=this.source.samples,rate=this.source.sampleRate;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#57d9b1';ctx.beginPath();for(let x=0;x<canvas.width;x++){const time=this.viewStart+x/canvas.width*this.viewSpan,next=time+this.viewSpan/canvas.width,mapped=this.waveSourceTime(time);let lo=0,hi=0;if(mapped!==null){const a=Math.floor(mapped*rate),mappedNext=this.waveSourceTime(next),b=Math.min(samples.length,Math.max(a+1,Math.floor((mappedNext===null?this.end:mappedNext)*rate)));for(let i=a;i<b;i++){lo=Math.min(lo,samples[i]||0);hi=Math.max(hi,samples[i]||0);}}ctx.moveTo(x,132-lo/32768*70);ctx.lineTo(x,132-hi/32768*70);}ctx.stroke();},

    setStart(value){if(!Number.isFinite(value))return;const previous=this.start;this.start=Math.max(0,this.start-this.offset/this.stretch,Math.min(this.end-this.minimum,value));this.offset=Math.max(0,this.offset+(this.start-previous)*this.stretch);},
    setEnd(value){if(!Number.isFinite(value))return;this.end=Math.min(this.duration,Math.max(this.start+this.minimum,value));},
    begin(event,kind){event.preventDefault();this.$emit('editing');event.currentTarget.setPointerCapture(event.pointerId);this.drag={kind,x:event.clientX,start:this.start,end:this.end,offset:this.offset,span:this.viewSpan/this.stretch,width:this.$refs.track.getBoundingClientRect().width};},
    move(event){if(!this.drag)return;const delta=(event.clientX-this.drag.x)/this.drag.width*this.drag.span;if(this.drag.kind==='start')this.setStart(this.drag.start+delta);else if(this.drag.kind==='end')this.setEnd(this.drag.end+delta);else this.setOffset(this.drag.offset+delta*this.stretch);},
    finish(){if(!this.drag)return;this.drag=null;this.commit();},
    step(kind,delta){kind==='start'?this.setStart(this.start+delta):this.setEnd(this.end+delta);this.commit();},
    shift(delta){this.setOffset(this.offset+delta);this.commit();},
    updateStretch(value,origin=null){if(origin)this.end=origin.end;this.stretch=Math.max(.1,Math.min(2,value));},
    revealSelection(){this.overview();},
    setStretch(value){if(!Number.isFinite(value))return;this.updateStretch(value);this.revealSelection();this.commit();},
    beginStretch(event){event.preventDefault();this.$emit('editing');event.currentTarget.setPointerCapture(event.pointerId);this.stretchDrag={x:event.clientX,factor:this.stretch,end:this.end,length:this.end-this.start,span:this.viewSpan,width:this.$refs.track.getBoundingClientRect().width};},
    moveStretch(event){if(!this.stretchDrag)return;const drag=this.stretchDrag;this.updateStretch(drag.factor+(event.clientX-drag.x)/drag.width*drag.span/drag.length,drag);},
    finishStretch(){if(!this.stretchDrag)return;this.stretchDrag=null;this.revealSelection();this.commit();},
    fitStretch(){this.stretch=Math.max(.1,Math.min(2,(this.maxDuration-this.offset)/(this.duration-this.start)));this.fit();this.revealSelection();},
    fit(){this.start=Math.min(this.start,Math.max(0,this.duration-this.minimum));this.end=Math.min(this.duration,this.start+Math.floor(this.selectionCapacity*this.source.sampleRate)/this.source.sampleRate);this.commit();},
    zoom(){this.viewSpan=Math.min(this.timelineDuration,Math.max(this.minimum*4,this.outputDuration*3));this.viewStart=Math.max(0,Math.min(this.timelineDuration-this.viewSpan,this.offset-(this.viewSpan-this.outputDuration)/2));this.$nextTick(()=>this.draw());},
    overview(){this.viewStart=0;this.viewSpan=this.timelineDuration;this.$nextTick(()=>this.draw());},
    full(){this.offset=0;this.start=0;this.end=this.duration;this.overview();this.commit();},
    setOffset(value){if(Number.isFinite(value))this.offset=Math.max(0,Math.min(Math.max(0,this.maxDuration-this.outputDuration),value));},
    setFade(kind,value){if(!Number.isFinite(value))return;this[kind==='in'?'fadeIn':'fadeOut']=Math.max(0,Math.min(Math.max(0,this.outputDuration-this[kind==='in'?'fadeOut':'fadeIn']),value));},
    stepFade(kind,delta){this.setFade(kind,this[kind==='in'?'fadeIn':'fadeOut']+delta);this.commit();},
    beginFade(event,kind){event.preventDefault();this.$emit('editing');event.currentTarget.setPointerCapture(event.pointerId);this.fadeDrag={kind,x:event.clientX,y:event.clientY,value:this[kind==='in'?'fadeIn':'fadeOut'],curve:this[kind==='in'?'fadeInCurve':'fadeOutCurve'],width:this.$refs.track.getBoundingClientRect().width};},
    moveFade(event){if(!this.fadeDrag)return;const d=this.fadeDrag;this.setFade(d.kind,d.value+(event.clientX-d.x)/d.width*this.viewSpan*(d.kind==='in'?1:-1));this[d.kind==='in'?'fadeInCurve':'fadeOutCurve']=Math.max(.2,Math.min(5,d.curve+(event.clientY-d.y)/60));},
    finishFade(){if(!this.fadeDrag)return;this.fadeDrag=null;this.commit();},
    commit(){this.fadeIn=Math.min(this.fadeIn,this.outputDuration);this.fadeOut=Math.min(this.fadeOut,Math.max(0,this.outputDuration-this.fadeIn));this.$emit('range',{start:this.start,end:this.end,stretch:this.stretch,offset:this.offset,fadeIn:this.fadeIn,fadeOut:this.fadeOut,fadeInCurve:this.fadeInCurve,fadeOutCurve:this.fadeOutCurve});},
  },
};
</script>
<style scoped>
.duration-summary{display:flex;align-items:center;flex-wrap:wrap;gap:6px;font-size:14px;margin:10px 12px 0;color:#344b62}.duration-summary strong{font-variant-numeric:tabular-nums}.duration-summary span{margin:0 6px;color:#176be0}.stretch-value{color:#bd3535;font-variant-numeric:tabular-nums}.stretch-handle{position:absolute;top:76px;width:28px;height:62px;margin:0;padding:0;transform:translateX(-50%);background:#bd3535;color:white;border:2px solid white;border-radius:6px;cursor:ew-resize;touch-action:none;font-size:20px;z-index:4}.stretch-handle:focus-visible{outline:3px solid #f4b13d}.stretch-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:12px 0}.stretch-actions button{font:inherit;padding:7px;border:1px solid #bbc8d6;border-radius:5px;background:white;cursor:pointer}.stretch-warning{color:#a32121;font-size:14px}.audio-import{margin:20px 0}.audio-drop{display:flex;flex-direction:column;align-items:center;gap:8px;padding:22px;border:2px dashed #92abc5;border-radius:10px;background:#f0f5fa;cursor:pointer}.audio-drop.dragging{background:#deedff;border-color:#176be0}.audio-drop span{font-size:14px;color:#516579}.audio-drop input{max-width:100%}.trim-editor{margin-top:16px;padding:18px;border:1px solid #c9d6e3;border-radius:10px;background:white}.trim-editor header{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap}.trim-editor header span{font-size:13px;color:#506477}.trim-track{position:relative;height:140px;margin:20px 12px 0;touch-action:none;background:#edf4fa;border-radius:6px;overflow:hidden}.view-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.view-controls button{font:inherit;background:#f9fbfd;padding:5px 8px;border:1px solid #bbc8d6;border-radius:5px}.view-controls label{display:flex;align-items:center;gap:8px}.view-controls input{width:180px}.trim-track canvas{width:100%;height:140px;display:block}.trim-selection{position:absolute;top:0;bottom:0;border:2px solid #176be0;box-sizing:border-box;background:#176be018;cursor:grab;touch-action:none}.trim-selection:active{cursor:grabbing}.trim-handle{position:absolute;top:-6px;height:152px;width:20px;transform:translateX(-50%);padding:0;margin:0;background:#176be0;color:white;border:2px solid white;border-radius:5px;cursor:ew-resize;touch-action:none;z-index:2}.trim-handle:focus-visible,.trim-selection:focus-visible{outline:3px solid #f4b13d}.time-axis{display:flex;justify-content:space-between;margin:6px 12px;color:#526679;font-size:12px}.trim-controls{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:16px 0}.trim-controls input{width:88px}.trim-controls button,.trim-controls input,.trim-editor>button{font:inherit;padding:7px;border:1px solid #bbc8d6;border-radius:5px;background:#f9fbfd}.trim-editor>button{margin-right:8px;cursor:pointer}.trim-controls button:disabled{opacity:.45}.trim-capacity{height:8px;background:#e4edf5;border-radius:4px;overflow:hidden}.trim-capacity span{display:block;height:100%;background:#288964}.trim-status{font-size:14px;color:#23634b}.trim-hint{font-size:14px;color:#516579}
.timeline-ruler{display:flex;justify-content:space-between;margin:20px 12px 0;padding:10px 0;color:#9cabb8;background:#232b32;font:11px monospace}.trim-track{height:220px;margin-top:0;border-radius:0;background:#20272e}.trim-track canvas{height:220px;position:relative;pointer-events:none}.target-region{position:absolute;top:0;bottom:0;background:repeating-linear-gradient(90deg,transparent,transparent calc(100% / 6 - 1px),#ffffff0d calc(100% / 6))}.clip-fill{position:absolute;top:38px;bottom:8px;background:#104b41;border:1px solid #3fae91;border-radius:4px}.clip-fill.overflow{border-color:#ef7777}.trim-selection{top:38px;bottom:8px;border:1px solid #77d9bb;background:transparent}.clip-title{display:block;background:#217b67;color:#e6fff6;padding:5px 24px;font-size:12px;white-space:nowrap;overflow:hidden}.trim-handle{top:82px;height:124px;width:12px;background:#82ceb9;color:#14392d;border:0;border-radius:2px;z-index:5}.stretch-handle{top:40px;height:24px;width:26px;background:#26483f;border:1px solid #9ce3ce;transform:translateX(-100%);z-index:7;font-size:18px}.marker{position:absolute;top:0;bottom:0;border-left:1px dashed #dfc06c;z-index:4;pointer-events:none}.marker span{position:absolute;top:6px;white-space:nowrap;color:#f4d784;font-size:11px;left:5px}.marker-end span{left:auto;right:5px}.fade-envelope{position:absolute;top:66px;height:142px;pointer-events:none;z-index:3;overflow:visible}.fade-envelope path{fill:none;stroke:#f0cf68;stroke-width:2;vector-effect:non-scaling-stroke}.fade-handle{position:absolute;top:67px;transform:translateX(-50%);width:22px;height:22px;padding:0;background:#f0cf68;color:#403513;border:1px solid #fff1ac;border-radius:3px;cursor:crosshair;touch-action:none;z-index:6}.trim-selection:focus-visible,.fade-handle:focus-visible{outline:2px solid #fff}.trim-editor button:disabled{opacity:.45}
</style>
